// spec: specs/ui-general.md §9 · кейс .qa/tests/ui-general/ui-15-ai-balance-error.md
// #38e1e5 (עבר QA 28.10): когда у провайдера AI кончился баланс, во ВСЕХ AI-местах показывается понятное сообщение
//   «…אינו זמין כרגע: השירות מושבת זמנית אצל הספק (נגמרה יתרת השימוש), ולכן ניסיון חוזר לא יעזור…» — независимо от поля
//   ответа (error / error.message / message / detail) и статуса (200 / 400); обычная ошибка (timeout) — прежний текст «נסה שוב» / «נכשל».
// Ответы AI-функций ПОДМЕНЕНЫ (page.route) — настоящего (платного) вызова нет; запись в базу из окна заблокирована и проверяется, что её не было.
// #746c35 (18.11): отклонённый ключ AI (detail:'auth') — «…החיבור לספק נדחה…», без «נסה שוב» и без сырого текста провайдера (кейс ui-17).
// Обновлено 29.10 (#6ac0be): в тесте импорта — новая подсказка у полей без колонки и кнопка привязки колонки.
// Порядок вариантов чередует «баланс» и «обычная ошибка», чтобы каждый клик менял текст (нет ложного зелёного от старого сообщения).
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { VARIANTS, BALANCE_TEXT, mockAi, blockWrites, AiMock } from '../_ai-mock';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
const IMG = path.resolve(__dirname, '../../fixtures/qa-auto-catalog.png');
const ORDER = ['error-200', 'timeout-200', 'error-400', 'timeout-500', 'error.message-200', 'timeout-200', 'error.message-400', 'timeout-500', 'message-200', 'timeout-200', 'detail-200', 'timeout-500'];

type Texts = { balance: string; generic: string };
const T = {
  list: { balance: `קריאת הרשימה אינה זמינה כרגע: ${BALANCE_TEXT} בינתיים חפשו את המוצרים בקטלוג.`, generic: 'לא הצלחנו לקרוא את הרשימה. נסה שוב, או חפש את המוצרים בקטלוג.' },
  photo: { balance: `זיהוי מוצר מתמונה אינו זמין כרגע: ${BALANCE_TEXT} בינתיים חפשו את המוצר בקטלוג.`, generic: 'לא הצלחנו לזהות את המוצר בתמונה. נסה שוב, או חפש את המוצר בקטלוג.' },
  describe: { balance: `הניסוח האוטומטי אינו זמין כרגע: ${BALANCE_TEXT} אפשר לכתוב את התיאור ידנית.`, generic: 'הניסוח נכשל. אפשר לנסות שוב או לכתוב את התיאור ידנית.' },
  import: { balance: `זיהוי עמודות אוטומטי אינו זמין כרגע: ${BALANCE_TEXT} שייכו את העמודות שנותרו ידנית.`, generic: 'לא הצלחנו לזהות את שאר העמודות אוטומטית. שייכו אותן ידנית.' },
  recommend: { balance: `רענון ההמלצות אינו זמין כרגע: ${BALANCE_TEXT}`, generic: 'רענון ההמלצות נכשל. בדוק את החיבור ונסה שוב.' },
} satisfies Record<string, Texts>;

/** Один вариант: подменить ответ, выполнить действие, дождаться одного вызова и нужного текста. */
async function check(page: Page, ai: AiMock, v: string, texts: Texts, act: () => Promise<void>, after?: () => Promise<void>) {
  const { status, body, balance } = VARIANTS[v];
  ai.set(status, body);
  const h0 = ai.hits;
  await act();
  await expect.poll(() => ai.hits, { message: `${v}: один вызов AI`, timeout: 15_000 }).toBe(h0 + 1);
  if (after) await after();
  const want = balance ? texts.balance : texts.generic;
  const other = balance ? texts.generic : texts.balance;
  await expect(page.getByText(want, { exact: true }).first(), `${v}: «${want.slice(0, 40)}…»`).toBeVisible({ timeout: 15_000 });
  await expect(page.getByText(other, { exact: true }), `${v}: нет другого текста`).toHaveCount(0);
}

test.describe('AI — הודעה ברורה כשנגמרה יתרת השימוש אצל הספק (#38e1e5), מפיץ', () => {
  test.use({ storageState: auth('admin') });

  test('«הזמנה מהודעה» /orders/new — «קריאת הודעה»: יתרה ב-error/error.message/message/detail, 200/400 → «קריאת הרשימה אינה זמינה כרגע…»; timeout → «נסה שוב» #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'order-photo');
    await page.goto('/orders/new');
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('combobox').fill('test');
    await page.getByRole('option').filter({ has: page.getByText('test', { exact: true }) }).first().click();
    await expect(page.getByText('איש קשר')).toBeVisible();
    await page.getByRole('textbox', { name: 'הודעת ההזמנה' }).fill('2 אבן לזיפו\n1 אינפיניטי אדום');
    const btn = page.getByRole('button', { name: 'קריאת הודעה' });
    for (const v of ORDER) {
      await expect(btn).toBeEnabled({ timeout: 15_000 });
      await check(page, ai, v, T.list, () => btn.click());
    }
    expect(writes, 'ничего не записано').toEqual([]);
  });

  // #746c35 (2026-11-18): ключ AI отклонён провайдером (401 invalid x-api-key) → «הזמנה מהודעה» показывает понятный текст без «נסה שוב»
  //   и без сырого текста провайдера. Ответ order-photo подменён (page.route): {ok:false, code:'MODEL_FAILED', detail:'auth'} (+ сырой текст в error).
  test('«הזמנה מהודעה» /orders/new — «קריאת הודעה»: ключ отклонён (detail:"auth", в error — invalid x-api-key / request_id) → «…מושבת זמנית אצל הספק (החיבור לספק נדחה), ולכן ניסיון חוזר לא יעזור…», без «נסה שוב» и без текста провайдера #746c35 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'order-photo');
    await page.goto('/orders/new');
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('combobox').fill('test');
    await page.getByRole('option').filter({ has: page.getByText('test', { exact: true }) }).first().click();
    await expect(page.getByText('איש קשר')).toBeVisible();
    await page.getByRole('textbox', { name: 'הודעת ההזמנה' }).fill('2 אבן לזיפו');
    const btn = page.getByRole('button', { name: 'קריאת הודעה' });
    const AUTH_TEXT = 'קריאת הרשימה אינה זמינה כרגע: השירות מושבת זמנית אצל הספק (החיבור לספק נדחה), ולכן ניסיון חוזר לא יעזור. בינתיים חפשו את המוצרים בקטלוג.';
    const RAW = 'authentication_error: invalid x-api-key (request_id: req_011CQ-QA-AUTO)';
    // чередуем с обычной ошибкой, чтобы каждый клик менял текст (нет ложного зелёного от старого сообщения)
    const cases: { name: string; status: number; body: unknown; auth: boolean }[] = [
      { name: 'auth + сырой текст в error', status: 200, body: { ok: false, code: 'MODEL_FAILED', detail: 'auth', error: RAW }, auth: true },
      { name: 'timeout', status: 200, body: { ok: false, code: 'MODEL_FAILED', error: 'Request timed out' }, auth: false },
      { name: 'auth без error', status: 200, body: { ok: false, code: 'MODEL_FAILED', detail: 'auth' }, auth: true },
    ];
    for (const c of cases) {
      ai.set(c.status, c.body);
      const h0 = ai.hits;
      await expect(btn).toBeEnabled({ timeout: 15_000 });
      await btn.click();
      await expect.poll(() => ai.hits, { message: `${c.name}: один вызов AI`, timeout: 15_000 }).toBe(h0 + 1);
      if (c.auth) {
        const msg = page.getByText(AUTH_TEXT, { exact: true });
        await expect(msg.first(), `${c.name}: текст про отклонённое подключение`).toBeVisible({ timeout: 15_000 });
        await expect(msg.first(), `${c.name}: без «נסה שוב»`).not.toContainText('נסה שוב');
        await expect(page.getByText(T.list.generic, { exact: true }), `${c.name}: нет общего текста`).toHaveCount(0);
        const main = page.locator('main');
        for (const raw of [/invalid x-api-key/i, /authentication_error/i, /request_id/i, /req_011CQ/]) {
          await expect(main, `${c.name}: нет текста провайдера ${raw}`).not.toContainText(raw);
        }
      } else {
        await expect(page.getByText(T.list.generic, { exact: true }).first(), `${c.name}: прежний текст «נסה שוב»`).toBeVisible({ timeout: 15_000 });
        await expect(page.getByText(AUTH_TEXT, { exact: true }), `${c.name}: нет текста про ключ`).toHaveCount(0);
      }
    }
    expect(writes, 'ничего не записано').toEqual([]);
  });

  test('«ניסוח תיאור» /catalog/new: יתרה → «הניסוח האוטומטי אינו זמין כרגע…»; timeout → «הניסוח נכשל…»; בלי שמירה #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'describe');
    await page.goto('/catalog/new');
    await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('textbox', { name: /שם מוצר/ }).fill('QA-AUTO-38e1e5 בדיקה');
    const btn = page.getByRole('button', { name: 'ניסוח תיאור' });
    for (const v of ORDER) {
      await expect(btn).toBeEnabled({ timeout: 15_000 });
      await check(page, ai, v, T.describe, () => btn.click());
    }
    await page.getByRole('button', { name: 'ביטול', exact: true }).first().click();
    expect(writes, 'товар не сохранялся').toEqual([]);
  });

  test('ייבוא /catalog/import — «שינוי עמודות»: יתרה → «זיהוי עמודות אוטומטי אינו זמין כרגע…»; timeout → «לא הצלחנו לזהות את שאר העמודות…»; בלי ייבוא #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(240_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'import-map');
    const csv = { name: 'qa-auto-38e1e5.csv', mimeType: 'text/csv', buffer: Buffer.from('מוצר,זרזיף קרפלוני\nQA-AUTO-38e1e5 בדיקה,7\n', 'utf8') };
    for (const v of ORDER) {
      await page.goto('/catalog/import');
      await check(page, ai, v, T.import,
        () => page.locator('input[type=file]').first().setInputFiles(csv),
        () => page.getByRole('button', { name: 'שינוי עמודות' }).first().click());
      // #6ac0be (29.10): при ошибке модели ручная привязка доступна — у поля без колонки новая подсказка
      // (прежнего «לא נמצאה עמודה בקובץ» при нераспознанной колонке нет), колонка «זרזיף קרפלוני» — кнопка привязки.
      const base = page.getByRole('listitem').filter({ has: page.getByText('מחיר בסיס', { exact: true }) }).first();
      await expect(base, `${v}: подсказка у поля без колонки`).toContainText('לא זוהתה עמודה · אפשר לשייך עמודה מהרשימה למטה');
      await expect(page.getByRole('button', { name: 'שיוך העמודה «זרזיף קרפלוני» לנתון', exact: true }), `${v}: кнопка колонки`).toBeVisible();
    }
    expect(writes, 'ничего не импортировано').toEqual([]);
  });

  test('«רענון המלצות» /settings: יתרה → «רענון ההמלצות אינו זמין כרגע…»; timeout → «רענון ההמלצות נכשל…» #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'recommend');
    await page.goto('/settings');
    const btn = page.getByRole('button', { name: 'רענון המלצות' });
    await expect(btn).toBeVisible({ timeout: 30_000 });
    for (const v of ORDER) {
      await expect(btn).toBeEnabled({ timeout: 15_000 });
      await check(page, ai, v, T.recommend, () => btn.click());
    }
    expect(writes, 'ничего не записано').toEqual([]);
  });

  test('קליטה «הוספת פריט למלאי» — «זיהוי מוצר מתמונה»: יתרה → «זיהוי מוצר מתמונה אינו זמין כרגע…»; timeout → «נסה שוב»; בלי קליטה #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(300_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'order-photo');
    for (const v of ORDER) {
      await page.goto('/catalog');
      await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
      await page.getByRole('button', { name: /^קליטת מלאי/ }).first().click();
      await expect(page.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible({ timeout: 15_000 });
      await page.getByRole('button', { name: 'זיהוי מוצר מתמונה' }).first().click();
      await expect(page.getByRole('heading', { name: 'מוצר מתמונה' })).toBeVisible({ timeout: 15_000 });
      await check(page, ai, v, T.photo, () => page.locator('input[type=file]').last().setInputFiles(IMG));
    }
    expect(writes, 'ничего не принято на склад').toEqual([]);
  });
});

test.describe('AI — הודעה ברורה כשנגמרה יתרת השימוש (#38e1e5), לקוח «הזמנה מהירה»', () => {
  test.use({ storageState: auth('buyer') });

  test('«הזמנה מהירה» — «קריאת הרשימה» (order-text): יתרה → «קריאת הרשימה אינה זמינה כרגע…»; timeout → «נסה שוב» #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'order-text');
    await page.goto('/shop');
    await page.getByRole('button', { name: 'הזמנה מהירה — הדבקת רשימה' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg).toBeVisible({ timeout: 15_000 });
    await dlg.locator('textarea').fill('2 אבן לזיפו\n1 אינפיניטי אדום');
    const btn = dlg.getByRole('button', { name: 'קריאת הרשימה' });
    for (const v of ORDER) {
      await expect(btn).toBeEnabled({ timeout: 15_000 });
      await check(page, ai, v, T.list, () => btn.click());
    }
    expect(writes, 'корзина/заказ не менялись').toEqual([]);
  });

  test('«הזמנה מהירה» — «זיהוי מוצר מתמונה» (order-photo): יתרה → «זיהוי מוצר מתמונה אינו זמין כרגע…»; timeout → «נסה שוב» #38e1e5 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(300_000);
    const writes = await blockWrites(page);
    const ai = await mockAi(page, 'order-photo');
    for (const v of ORDER) {
      await page.goto('/shop');
      await page.getByRole('button', { name: 'הזמנה מהירה — הדבקת רשימה' }).click();
      await page.getByRole('button', { name: 'זיהוי מוצר מתמונה' }).click();
      await expect(page.getByRole('heading', { name: 'מוצר מתמונה' })).toBeVisible({ timeout: 15_000 });
      await check(page, ai, v, T.photo, () => page.locator('input[type=file]').last().setInputFiles(IMG));
    }
    expect(writes, 'корзина/заказ не менялись').toEqual([]);
  });
});
